const memberState={booked:false,waitlisted:false,attended:false,profile:'adult',cancelledMembership:false,frozen:false,waiverSigned:true,payment:'current',childWaiver:false,childBooked:false,childBookingDate:'fri',childAttended:false,childLateConsumed:false,childCancelledMembership:false,childFrozen:false,bookingPending:false,pendingOperation:null,funding:'membership',bookingDate:'fri',bookingClassId:'beginner-muay',waitlistSelection:null,lateConsumed:false,packAvailable:3,paidExtra:false,cardUpdated:false,formVersion:'3.1',day:'fri',program:'all',trialBooked:false,trialSigned:false,trialStep:1,trialPaid:false,exportReady:false};
const memberName=()=>memberState.profile==='child'?'Eli Chen':'Maya Chen';
const memberBooked=()=>memberState.profile==='child'?memberState.childBooked:memberState.booked;
const memberSigned=()=>memberState.profile==='child'?memberState.childWaiver:memberState.waiverSigned;
