const memberBookingPending=()=>memberState.bookingPending&&memberState.pendingOperation?.profile===memberState.profile;
let bookingSelection={profile:'adult',classId:'beginner-muay',day:'fri'};
let waitlistSelection=null;
let memberMoveSelection=null;
const memberCancelled=()=>memberState.profile==='child'?memberState.childCancelledMembership:memberState.cancelledMembership;
const memberFrozen=()=>memberState.profile==='child'?memberState.childFrozen:memberState.frozen;
const memberFreezeApproved=()=>memberState.profile==='adult'&&adminState.freeze==='scheduled';
function memberLimits(profile=memberState.profile){if(profile==='child')return {weekly:2,monthly:8};return {weekly:['unlimited','monthly-only'].includes(uiState.scenario)?null:2,monthly:['unlimited','weekly-only'].includes(uiState.scenario)?null:8};}
function memberHasLimits(){const l=memberLimits();return l.weekly!==null||l.monthly!==null;}
function memberLimitLabel(){const l=memberLimits();return [l.weekly===null?'':`${l.weekly} classes per training week`,l.monthly===null?'':`${l.monthly}${l.weekly===null?' classes':''} per billing month`].filter(Boolean).join(' · ')||'Unlimited classes';}
function memberUsesPack(){return memberState.profile==='adult'&&memberState.funding==='pack';}
function memberPackAvailable(){return memberState.profile==='child'?0:Math.max(0,memberState.packAvailable-(memberState.booked&&memberUsesPack()?1:0));}

function memberScheduleDate(day){return csDate(Number(demoDays[day]?.date||9));}
function memberOccurrence(selection){return csOccurrence(selection.classId,memberScheduleDate(selection.day==='mon'?'next-mon':selection.day));}
function memberScheduleProblem(message){
 const body=root.querySelector('#hl-overlay:not([hidden]) .hl-dialog-body');
 if(body){let error=body.querySelector('[data-schedule-error]');if(!error){error=document.createElement('div');error.dataset.scheduleError='true';body.prepend(error);}error.innerHTML=notice('Class could not be confirmed',esc(message),'danger');}
 else toast(message);
 return false;
}
function memberOccurrenceKey(selection){const item=selection.profile==='child'?null:memberOccurrence(selection);return JSON.stringify(item?['title','program','coach','space','start','end','level'].map(key=>item[key]):selection.profile==='child'?['juniors','16:30','17:15']:null);}
function memberBookingKey(){return JSON.stringify([currentBookingSelection(),memberUsesPack()?'pack':'membership']);}
function memberClassAvailable(selection,quiet=false){
 if(selection.profile==='child')return true;
 const item=memberOccurrence(selection),held=memberState.booked&&memberState.bookingClassId===selection.classId&&bookingScheduleDay(currentBookingSelection())===bookingScheduleDay(selection);
 const problem=!item?'This class is no longer scheduled. Choose another class.':item.level?'This class requires a higher training level.':!held&&csBooked(item.id,memberScheduleDate(bookingScheduleDay(selection)))>=item.capacity?'This class is full. Choose another class or review its waitlist.':!held&&csWaitlisted(item.id,memberScheduleDate(bookingScheduleDay(selection)))>0?'The waitlist gets the next available places. Join or review the waitlist for this class.':null;
 if(problem&&!quiet)memberScheduleProblem(problem);return !problem;
}
function sessionInfo(selection){
 const child=selection.profile==='child',key=selection.day==='mon'?'next-mon':selection.day;
 const item=child?{id:'juniors',title:'Taekwondo juniors',start:'16:30',end:'17:15',coach:'Alex Park',space:'Mat 1'}:memberOccurrence(selection)||csSeries(selection.classId)||demoClass('beginner-muay');
 const [hours,minutes]=item.start.split(':').map(Number),cutoffDate=new Date(Date.UTC(2026,9,demoDays[key].date,hours-6,minutes));
 const cutoffTime=`${String(cutoffDate.getUTCHours()).padStart(2,'0')}:${String(cutoffDate.getUTCMinutes()).padStart(2,'0')}`;
 return {child,mon:key==='next-mon',classId:item.id,day:demoDayLabel(key),time:demoClassRange(item),title:esc(item.title),coach:esc(classCoachLabel(item)),space:esc(item.space),cutoff:`${cutoffDate.getUTCDate()} ${cutoffDate.toLocaleDateString('en-GB',{month:'short',timeZone:'UTC'})} · ${demoTimeLabel(cutoffTime)}`};
}
function currentBookingSelection(){return {profile:memberState.profile,classId:memberState.profile==='child'?'juniors':memberState.bookingClassId,day:memberState.profile==='child'?memberState.childBookingDate:memberState.bookingDate};}
function bookingInfo(){return {...sessionInfo(currentBookingSelection()),funding:memberUsesPack()?'Punch card · 1 unit '+(memberAttended()?'used':'reserved'):memberHasLimits()?'Membership · 1 class':'Membership · Unlimited classes'};}
function waitlistInfo(){return sessionInfo(memberState.waitlistSelection||{profile:'adult',classId:'padwork',day:'sat'});}
function memberWaitlistPosition(selection){const joined=memberState.waitlisted&&memberState.waitlistSelection?.classId===selection.classId&&bookingScheduleDay(memberState.waitlistSelection)===bookingScheduleDay(selection);return csWaitlisted(selection.classId,memberScheduleDate(bookingScheduleDay(selection)))+(joined?0:1);}
function memberWaitlistAvailable(selection){
 if(memberState.profile!=='adult'||!selection||!['fri','sat','sun','next-mon'].includes(bookingScheduleDay(selection)))return memberScheduleProblem('Choose an upcoming adult class.');
 const item=memberOccurrence(selection);if(!item)return memberScheduleProblem('This class is no longer scheduled. Choose another class.');if(item.level)return memberScheduleProblem('This class requires advanced training approval.');
 if(item.places>0&&item.waitlist===0)return memberScheduleProblem('A place is available. Review a direct booking for this class.');
 return true;
}
function allowance(){
  const child=memberState.profile==='child',limits=memberLimits(),date=child?memberState.childBookingDate:memberState.bookingDate,late=child?memberState.childLateConsumed:memberState.lateConsumed;
  const consumed=child?(late&&date!=='mon'?1:0)+(memberState.childAttended&&date!=='mon'?1:0):(uiState.scenario==='limit'?2:1)+(late&&date!=='mon'?1:0)+(memberState.attended&&memberState.funding==='membership'&&date!=='mon'?1:0);
  const held=child?(memberState.childBooked&&!memberState.childAttended&&memberState.childBookingDate!=='mon'?1:0):(memberState.booked&&!memberState.attended&&memberState.funding==='membership'&&memberState.bookingDate!=='mon'?1:0);
  const monthUsed=child?2+(memberState.childLateConsumed?1:0)+(memberState.childAttended?1:0):(uiState.scenario==='monthly'?8:4)+(uiState.scenario==='limit'?1:0)+(memberState.lateConsumed?1:0)+(memberState.attended&&memberState.funding==='membership'?1:0);
  const monthHeld=child?(memberState.childBooked&&!memberState.childAttended?1:0):(memberState.booked&&!memberState.attended&&memberState.funding==='membership'?1:0);
  const futureUsed=(late&&date==='mon'?1:0)+(memberAttended()&&!memberUsesPack()&&date==='mon'?1:0),futureHeld=memberBooked()&&!memberAttended()&&!memberUsesPack()&&date==='mon'?1:0;
  return {consumed,held,monthUsed,monthHeld,remaining:limits.weekly===null?null:Math.max(0,limits.weekly-consumed-held),monthly:limits.monthly===null?null:Math.max(0,limits.monthly-monthUsed-monthHeld),futureWeekly:limits.weekly===null?null:Math.max(0,limits.weekly-futureUsed-futureHeld)};
}
function allowanceBlock(){const a=allowance(),l=memberLimits();if(!memberHasLimits())return '';const period=(key,title,available,used,reserved,limit,dates,reset)=>`<div class="hl-allowance-period" data-period="${key}"><h3>${title}</h3><p class="hl-allowance-value"><span class="hl-allowance-num">${available}</span> <span class="hl-allowance-label">available to book</span></p><p class="hl-allowance-detail">${used} used · ${reserved} reserved · <span style="white-space:nowrap">${limit}-class limit</span></p><p class="hl-allowance-reset">${dates} · Resets ${reset}</p></div>`;return `<section class="hl-panel hl-allowance-summary" aria-label="Class allowance"><div class="hl-allowance-grid">${l.weekly===null?'':period('week','This training week',a.remaining,a.consumed,a.held,l.weekly,'5–11 Oct','12 Oct')}${l.monthly===null?'':period('month','This billing month',a.monthly,a.monthUsed,a.monthHeld,l.monthly,'5 Oct–4 Nov','5 Nov')}</div>${a.remaining===0||a.monthly===0?'<p class="hl-allowance-policy">No membership classes available in this period.</p>':''}</section>`;}
function nextWeekAvailability(){const a=allowance();return [a.futureWeekly===null?'':`${a.futureWeekly} available in the 12–18 Oct week`,a.monthly===null?'':`${a.monthly} available this billing month`].filter(Boolean).join(' · ')||'Included in your unlimited membership';}
function allowanceExplanation(){const l=memberLimits();if(!memberHasLimits())return '';return `<details class="hl-disclosure"><summary>How your allowance works</summary><div class="hl-disclosure-body hl-timeline"><div><strong>Each reservation holds one class ${l.weekly!==null&&l.monthly!==null?'in both limits':l.weekly!==null?'in its training week':'in its billing month'}.</strong><p class="hl-muted hl-small">Attendance uses the allowance already reserved. It does not use a second class.</p></div>${l.weekly===null?'':`<div><strong>Weeks follow your billing cycle.</strong><p class="hl-muted hl-small">5–11 Oct · 12–18 Oct · 19–25 Oct · 26 Oct–1 Nov · 2–4 Nov. The final short week still has the full weekly cap of ${l.weekly}.</p></div>`}<div><strong>Corrections return to the original period.</strong><p class="hl-muted hl-small">A September correction does not refill October's allowance.</p></div></div></details>`;}

const bookingScheduleDay=selection=>selection.day==='mon'?'next-mon':selection.day;
function scheduleClassVisible(selection){return bookingScheduleDay(selection)===memberState.day&&(memberState.program==='all'||memberState.program===(selection.profile==='child'?'tkd':memberOccurrence(selection)?.program));}
function showMemberClass(selection){
 closeDialog({immediate:true,restoreFocus:false});
 memberState.day=bookingScheduleDay(selection);memberState.program='all';
 if(uiState.page==='m-schedule')render();else navigate('m-schedule');
 const main=root.querySelector('#hl-main'),day=memberState.day;
 const reveal=()=>{
  if(uiState.page!=='m-schedule'||memberState.profile!==selection.profile||memberState.day!==day)return;
  const row=[...main.querySelectorAll('.hl-class')].find(node=>node.dataset.class===selection.classId&&node.dataset.classDay===day);
  row?.scrollIntoView({block:'nearest'});row?.querySelector('button:not(:disabled)')?.focus({preventScroll:true});
 };
 if(main.getAttribute('aria-busy')==='true'){
  const observer=new MutationObserver(()=>{if(main.getAttribute('aria-busy')!=='true'){observer.disconnect();reveal();}});
  observer.observe(main,{attributes:true,attributeFilter:['aria-busy']});
 }else reveal();
}
function classStatusLinks(){
 const links=[];
 if(memberBooked()&&!scheduleClassVisible(currentBookingSelection())){const b=bookingInfo();links.push(act(`${memberAttended()?'Attended':'Booked'} · ${b.day} · ${b.title}`,'m-show-booking','ghost'));}
 if(memberBookingPending()&&!scheduleClassVisible(memberState.pendingOperation)){const b=sessionInfo(memberState.pendingOperation);links.push(act(`Pending · ${b.day} · ${b.title}`,'m-show-pending','ghost'));}
 if(memberState.profile==='adult'&&memberState.waitlisted&&!scheduleClassVisible(memberState.waitlistSelection)){const b=waitlistInfo();links.push(act(`Waitlisted · ${b.day} · ${b.title}`,'m-show-waitlist','ghost'));}
 return links.length?`<div class="hl-class-status-links" aria-label="Your classes on other dates or programs">${links.join('')}</div>`:'';
}
function classReminders(){
 const reminders=[];
 if(!memberSigned())reminders.push(notice('A signature is needed',`Complete the current training waiver for ${memberName()} before booking or check-in.`,'warning',go('Review waiver','m-forms','ghost')));
 if(memberState.profile==='adult'&&memberState.payment==='pending')reminders.push(notice('Payment confirmation pending','We’re checking your renewal payment. Review its status before paying again.','warning',go('Review payment','m-billing','ghost')));
 else if(memberState.profile==='adult'&&uiState.scenario==='debt'&&memberState.payment!=='settled')reminders.push(notice('Your renewal needs attention','Your grace period ends 12 Oct at 23:59. Updating your card does not settle the invoice.','warning',go('Review payment','m-billing','ghost')));
 return reminders.join('');
}
function memberClassesView(){
 const next=memberState.day==='next-mon';
 const dates=next?[['next-mon','Mon','12']]:[['mon','Mon','5'],['tue','Tue','6'],['wed','Wed','7'],['thu','Thu','8'],['fri','Fri','9'],['sat','Sat','10'],['sun','Sun','11']];
 return `<div class="hl-stack">${classReminders()}${allowanceBlock()}${section('Class schedule',`<div class="hl-between"><span class="hl-small hl-muted">${next?'Monday, 12 October 2026':'5–11 October 2026'}</span>${field('Program',`<select id="m-program" class="hl-select"><option value="all" ${memberState.program==='all'?'selected':''}>All programs</option><option value="muay" ${memberState.program==='muay'?'selected':''}>Muay Thai</option><option value="hiit" ${memberState.program==='hiit'?'selected':''}>HIIT / Hyrox</option><option value="padwork" ${memberState.program==='padwork'?'selected':''}>Padwork</option><option value="tkd" ${memberState.program==='tkd'?'selected':''}>Taekwondo</option><option value="bjj" ${memberState.program==='bjj'?'selected':''}>Jiu-jitsu</option></select>`)}</div>${classStatusLinks()}<div class="hl-days${next?' hl-next-day':''}" role="group" aria-label="Class date">${dates.map(([value,label,date])=>`<button type="button" data-action="m-day" data-day="${value}" class="hl-day" aria-pressed="${memberState.day===value}" aria-controls="hl-schedule-classes" aria-label="${label}, ${date} October 2026"><span>${label}</span><strong>${date}</strong></button>`).join('')}</div><div class="hl-between hl-class-date-heading"><h3>${demoDayLabel(memberState.day)}</h3>${act(next?'Back to this week':'Monday, 12 Oct',next?'m-show-friday':'m-next-monday','ghost')}</div><div id="hl-schedule-classes" aria-live="polite" aria-atomic="true">${memberDayClasses(memberState.day,memberState.program)}</div><div class="hl-class-history-link">${act('View class history','m-history','ghost')}</div>`)}</div>`;
}

function memberDayClasses(day,program='all'){
 const child=memberState.profile==='child',past=['mon','tue','wed','thu'].includes(day);
 if(child){
  if(['fri','next-mon'].includes(day)&&(program==='all'||program==='tkd')){
   const held=memberBooked()&&bookingScheduleDay(currentBookingSelection())===day;
   const pending=memberBookingPending()&&bookingScheduleDay(memberState.pendingOperation)===day;
   const action=held?act(memberAttended()?'Details':'Manage','m-manage-booking'):pending?act('Check status','m-recover'):memberBookingPending()?act('Confirmation pending','m-recover','secondary','disabled'):day==='next-mon'?act('Preview class','m-future'):act('Book for Eli','m-book','primary','data-class="juniors" data-day="fri"');
   return classRow('16:30','45 min','Taekwondo juniors','4:30pm–5:15pm · Alex Park · Ages 8–12',badge(pending?'Pending':held?(memberAttended()?'Attended':'Booked'):'4 places left',pending?'warning':held?'success':'neutral'),action,`data-class="juniors" data-class-day="${day}"`,'Mat 1');
  }
  return `<div class="hl-class-empty"><h3>No junior classes on ${demoDays[day].label}</h3><p>Choose Friday to book Eli’s class.</p>${act('Show Friday','m-show-friday','ghost','data-day="fri"')}</div>`;
 }
 const classes=csClassesOn(memberScheduleDate(day)).filter(item=>program==='all'||item.program===program);
 if(!classes.length)return emptyClasses();
 return classes.map(item=>{
  const held=memberBooked()&&bookingScheduleDay(currentBookingSelection())===day&&memberState.bookingClassId===item.id;
  const pending=memberBookingPending()&&bookingScheduleDay(memberState.pendingOperation)===day&&memberState.pendingOperation.classId===item.id;
  const places=Math.max(0,item.capacity-csBooked(item.id,memberScheduleDate(day))),waiting=csWaitlisted(item.id,memberScheduleDate(day)),listed=memberState.waitlisted&&memberState.waitlistSelection?.classId===item.id&&bookingScheduleDay(memberState.waitlistSelection)===day;
  const label=held?(memberAttended()?'Attended':'Booked'):pending?'Pending':listed?'Waitlisted · Position '+memberWaitlistPosition(memberState.waitlistSelection):past?'Past class':item.level?'Advanced approval required':places===0?'Full · waitlist open':waiting?'Waitlist gets next place':`${places} ${places===1?'place':'places'} left`;
  const attrs=`data-class="${item.id}" data-day="${day}"`,description=esc(item.title+' · '+demoDayLabel(day)+' · '+demoClassRange(item));
  let action;
  if(held)action=act(memberAttended()?'Details':'Manage','m-manage-booking','secondary',`aria-label="${memberAttended()?'View attendance for':'Manage booking for'} ${description}"`);
  else if(pending)action=act('Check status','m-recover','secondary',`aria-label="Check booking status for ${description}"`);
  else if(listed)action=act('Manage waitlist','m-manage-waitlist','secondary',`aria-label="Manage waitlist for ${description}"`);
  else if(past)action=act('Past class','m-past','secondary','disabled');
  else if(memberBookingPending())action=act('Confirmation pending','m-recover','secondary','disabled');
  else if(item.level)action=act('Check eligibility','m-rank','secondary',attrs+` aria-label="Check eligibility for ${description}"`);
  else if(places===0||waiting>0)action=act('Join waitlist','m-waitlist','secondary',attrs+` aria-label="Join waitlist for ${description}"`);
  else if(day==='next-mon')action=act('Preview class','m-future','secondary',attrs);
  else action=act('Book class','m-book','primary',attrs+` aria-label="Book ${description}"`);
  return classRow(item.start,item.duration+' min',item.title,`${demoClassRange(item)} · ${classCoachLabel(item)}${pending?' · Connection interrupted. Check your booking status.':''}`,badge(label,held?'success':pending||listed||places<2?'warning':'neutral'),action,`data-class="${item.id}" data-class-day="${day}"`,item.space);
 }).join('');
}
