 'm-account':{title:'Account',subtitle:'Your details, family access and personal records.',icon:'shield-check',navLabel:'Account',group:'Member portal',html:()=>`<div class="hl-stack"><div class="hl-grid">${section('Your details',`${person('Maya Chen','maya@example.test · Verified email','MC')}<hr class="hl-divider">${field('Display name','<input id="m-display-name" class="hl-input" value="Maya Chen">')}${field('Time zone','<select class="hl-select"><option>America/Vancouver</option></select>')}${act('Save details','m-save-account','primary')}`)}${section('Your records',`<p class="hl-small hl-muted">Download your profile, attendance, payments, agreements and shared coaching records. Private coach notes and other household members’ records are excluded.</p><div class="hl-row" style="margin-top:18px">${act(memberState.exportReady?'View export contents':'Request my export',memberState.exportReady?'m-export-manifest':'m-export','primary')}</div>${memberState.exportReady?notice('Export ready','Your records are ready to review.','success'):''}`)}</div>${section('Family',`<p class="hl-small hl-muted">Each person has their own records and balances.</p><div class="hl-list-row">${person('Eli Chen','Age 10 · Taekwondo juniors','EC')}${act('View permissions','m-family-eli','secondary','aria-label="View permissions for Eli Chen"')}</div><div class="hl-list-row">${person('Noah Chen','Age 7 · Access pending','NC')}${act('Review access','m-family-noah','secondary','aria-label="Review access for Noah Chen"')}</div>`)}</div>`},
