 'm-confirm-pack':()=>{if(memberPackAvailable()<1)return toast('No paid punches are available for '+memberName()+'.');commitBooking(true);},
 'm-recover':()=>{if(!memberState.pendingOperation)return toast('You have no pending booking to check.');commitBooking(memberState.pendingOperation.funding==='pack',memberState.pendingOperation.profile,memberState.pendingOperation);},
 'm-receipt':()=>{const b=bookingInfo();showDialog('Booking confirmation',`${badge(memberAttended()?'Attended':'Confirmed','success')}${details([['Reference',b.child?'BK-1085':'BK-1084'],['Participant',memberName()],['Class',b.title],['When',b.day+' · '+b.time],['Cancel without penalty',b.cutoff],['Funding',b.funding],['Policy','Booking terms v2.1'],['Notification','Queued · booking already confirmed']])}`,act('Done','close-dialog','primary'));},
 'm-rank':el=>{const selection={profile:memberState.profile,classId:el?.dataset.class||bookingSelection.classId,day:el?.dataset.day||bookingSelection.day},item=memberOccurrence(selection);if(!item)return memberScheduleProblem('This class is no longer scheduled. Choose another class.');const program={muay:'Muay Thai',hiit:'HIIT / Hyrox',padwork:'Padwork',tkd:'Taekwondo',bjj:'Jiu-jitsu'}[item.program]||item.program;showDialog('Class eligibility',`${badge('Not eligible yet','warning')}${details([['Class',esc(item.title)],['Program',esc(program)],['Requirement','Advanced training approval'],['Your record','Foundations'],['Set by','Northstar · program policy']])}<p class="hl-small hl-muted">Ask your coach to review your eligibility for this class.</p>`,act('Got it','close-dialog','primary'));},
 'm-waitlist':el=>{if(memberState.profile!=='adult')return;const selection={profile:'adult',classId:el?.dataset.class||'padwork',day:el?.dataset.day||'sat'};if(memberState.waitlisted){if(memberState.waitlistSelection?.classId===selection.classId&&bookingScheduleDay(memberState.waitlistSelection)===bookingScheduleDay(selection))return memberActions['m-manage-waitlist']();return memberScheduleProblem('Review your existing waitlist place before joining another class.');}if(!memberWaitlistAvailable(selection))return;waitlistSelection=selection;const b=sessionInfo(waitlistSelection);showDialog('Join the automatic waitlist',`<div class="hl-stack">${details([['Class',b.title],['When',b.day+' · '+b.time],['Member','Maya Chen'],['Position if joined',String(memberWaitlistPosition(selection))],['Automatic booking ends',b.cutoff]])}${notice('A waitlist place is not a booking',memberHasLimits()?'No allowance is held. If a place opens, we’ll check your eligibility and allowance before booking you automatically. Automatic booking stops before the late-cancellation window.':'No class place is held. If a place opens, we’ll check your eligibility before booking you automatically. Automatic booking stops before the late-cancellation window.')}<label class="hl-check"><input type="checkbox" id="m-waitlist-consent"> Automatically book me if an eligible place becomes available before the cutoff.</label></div>`,act('Back','close-dialog')+act('Join waitlist for Maya','m-confirm-waitlist','primary'));},
 'm-confirm-waitlist':()=>{if(memberState.waitlisted)return memberScheduleProblem('You already have a waitlist place. Review it before joining again.');if(!memberWaitlistAvailable(waitlistSelection))return;if(!root.querySelector('#m-waitlist-consent')?.checked){memberScheduleProblem('Accept automatic booking before joining the waitlist.');return;}memberState.waitlisted=true;memberState.waitlistSelection={...waitlistSelection};const position=memberWaitlistPosition(memberState.waitlistSelection);closeDialog();showMemberClass(memberState.waitlistSelection);toast(memberHasLimits()?'Maya is number '+position+' on the waitlist. No allowance was reserved.':'Maya is number '+position+' on the waitlist. Your unlimited membership is unchanged.');},
