 'm-cancel':()=>{if(memberAttended())return showDialog('Attendance already recorded',notice('Request a correction from the gym','You cannot cancel a class after attendance is recorded. The gym can correct the record while keeping the original funding and attendance history.'),act('Done','close-dialog','primary'));const late=uiState.scenario==='late',pack=memberUsesPack(),limited=memberHasLimits();return showDialog('Cancel this booking?',`<div class="hl-stack">${details([['Member',memberName()],['Class',bookingInfo().title],['When',bookingInfo().day+' · '+bookingInfo().time],['Cancellation',late?'After the penalty-free cutoff':'Before the penalty-free cutoff'],['Consequence',pack?(late?'Reserved punch used once under accepted terms':'Release the reserved punch'):limited?(late?'Reserved class used once under accepted terms':'Release the reservation in each capped period'):'Release your place; unlimited membership stays active'],['Cash refund','None · no new payment was taken']])}${notice(late?'Late cancellation':pack?'Your punch is released':limited?'Your allowance returns to its original period':'Your place is released',late?(pack?'The reserved punch counts once under your accepted policy. Cancelling again cannot use another.':limited?'The reserved class counts once in each capped period under your accepted policy. Cancelling again cannot use another.':'The late cancellation is recorded. Your unlimited membership has no class allowance to deduct.'):'The seat is released to the eligible waitlist. The membership remains active.',late?'warning':'info')}</div>`,act('Keep booking','close-dialog')+act('Cancel '+memberName()+'’s booking','m-confirm-cancel','danger'));},
 'm-confirm-cancel':()=>{if(!memberBooked())return toast('This booking is already cancelled.');if(memberAttended())return toast('Ask the gym to correct the attendance record. You cannot cancel a completed class.');const pack=memberUsesPack(),limited=memberHasLimits(),late=uiState.scenario==='late';if(memberState.profile==='child'){memberState.childBooked=false;if(late)memberState.childLateConsumed=true;}else{memberState.booked=false;memberState.attended=false;if(late){if(pack)memberState.packAvailable--;else memberState.lateConsumed=true;}}closeDialog();render();toast(late?(pack?'Booking cancelled. The reserved punch was used once under your late-cancellation policy.':limited?'Booking cancelled. The reserved class was used once in each capped period under your late-cancellation policy.':'Booking cancelled. Late cancellation recorded; your unlimited membership is unchanged.'):(pack?'Booking cancelled. Your reserved punch was released.':limited?'Booking cancelled. Your allowance was released to its original period.':'Booking cancelled. Your place was released; your unlimited membership is unchanged.'));},
 'm-move':()=>{memberMoveSelection=null;if(!memberBooked())return memberScheduleProblem('This booking is no longer active.');if(memberAttended())return memberScheduleProblem('You cannot move a class after attendance is recorded. Ask the gym to review the record.');const from=bookingInfo();if(from.mon)return memberScheduleProblem('You are already booked for the 12 Oct class.');const target={profile:memberState.profile,classId:currentBookingSelection().classId,day:'mon'};if(!memberClassAvailable(target))return;const to=sessionInfo(target),l=memberLimits(),pack=memberUsesPack();memberMoveSelection={target,original:memberBookingKey(),targetKey:memberOccurrenceKey(target)};return showDialog('Move your booking',`<div class="hl-stack">${details([['From',from.day+' · '+from.time+' · '+from.title],['To',to.day+' · '+to.time+' · '+to.title],['New coach / room',to.coach+' · '+to.space],['Member',memberName()],...(pack?[['Funding','Keep the same reserved punch']]:[...(l.weekly===null?[]:[['Original week','5–11 Oct · release one hold'],['New week','12–18 Oct · reserve one hold']]),...(l.monthly===null?[]:[['Same billing month','Keep one monthly allocation']]),...(!memberHasLimits()?[['Funding','Included in your unlimited membership']]:[])]),['If the new place is unavailable','Keep the original booking']])}${notice('Review before moving',pack?'You keep your original booking and punch reservation until the new place is confirmed.':memberHasLimits()?'You keep your original booking until the new place and allowance are confirmed.':'You keep your original booking until the new place is confirmed.')}</div>`,act('Keep original','close-dialog')+act('Move '+memberName()+'’s booking','m-confirm-move','primary'));},
 'm-confirm-move':()=>{const move=memberMoveSelection;if(!move)return memberScheduleProblem('Review the destination class before moving your booking.');if(!memberBooked())return memberScheduleProblem('The original booking is no longer active. No new booking was made.');if(memberAttended())return memberScheduleProblem('Attendance is already recorded. Your original booking is unchanged.');if(move.original!==memberBookingKey()||move.target.profile!==memberState.profile)return memberScheduleProblem('The original booking changed. Review it again before moving.');if(!memberClassAvailable(move.target))return;if(move.targetKey!==memberOccurrenceKey(move.target))return memberScheduleProblem('The destination class changed. Go back and review the new time, coach and room. Your original booking is unchanged.');const a=allowance();if(!memberUsesPack()&&a.futureWeekly!==null&&a.futureWeekly<1)return memberScheduleProblem('No weekly allowance is available for 12–18 Oct. Your original booking is unchanged.');if(memberState.profile==='child')memberState.childBookingDate='mon';else memberState.bookingDate='mon';memberMoveSelection=null;closeDialog();showMemberClass(currentBookingSelection());toast(memberUsesPack()?'Moved to 12 Oct using the same reserved punch.':memberLimits().monthly!==null?'Moved to 12 Oct using the same monthly allowance reservation.':memberLimits().weekly!==null?'Moved to 12 Oct. Your class reservation now uses the 12–18 Oct week.':'Moved to 12 Oct under your unlimited membership.');},
 'm-future':el=>{const selection={profile:memberState.profile,classId:memberState.profile==='child'?'juniors':el?.dataset.class||memberState.bookingClassId,day:'mon'};if(!memberClassAvailable(selection))return;const a=allowance(),l=memberLimits(),both=l.weekly!==null&&l.monthly!==null,b=sessionInfo(selection),sameClass=b.classId===currentBookingSelection().classId;return showDialog(memberHasLimits()?'Next-week allowance preview':'Next-week class preview',`${details([['Class',b.title+' · 12 Oct · '+b.time],['Coach / room',b.coach+' · '+b.space],...(l.weekly===null?[]:[['Weekly window','12–18 Oct · '+a.futureWeekly+' available']]),...(l.monthly===null?[]:[['Billing month','5 Oct–4 Nov · '+a.monthly+' available']]),['Funding',memberHasLimits()?'Membership allowance':'Unlimited membership'],['Billing coverage','Within your paid billing cycle']])}<p class="hl-small hl-muted">${memberHasLimits()?`New membership bookings need space in ${both?'both your weekly and monthly allowances':l.weekly!==null?'the class’s training week':'the class’s billing month'}. ${memberBooked()&&l.monthly!==null&&!memberUsesPack()?'Moving your existing booking keeps its monthly reservation. ':''}`:'Class capacity, waiver and eligibility requirements still apply. '}If a future renewal fails, the accepted payment policy applies to affected bookings.</p>`,memberBooked()?(bookingInfo().mon||!sameClass?act('View your booked class','m-show-booking','primary'):act('Move existing booking','m-move','primary')):act('Done','close-dialog','primary'));},
